parameters.jsCode:
const items = $input.all();
const results = [];

for (const item of items) {
  const meta = item.json.chart?.result?.[0]?.meta || item.json;
  const preco = meta.regularMarketPrice;
  const ticker = (meta.symbol || item.json.ticker || '').replace('.SA', '');

  // Buscar os alvos originais do item anterior
  const alvos = $('🔀 Um Item por Ativo').all();
  const alvo = alvos.find(a => a.json.ticker === ticker);

  if (!alvo) continue;

  const min = alvo.json.min;
  const max = alvo.json.max;
  const nome = meta.longName || meta.shortName || ticker;

  let alerta = null;
  let tipo = null;

  if (preco !== undefined && preco !== null) {
    if (min !== undefined && preco <= min) {
      alerta = `⬇️ ${ticker} caiu para R$ ${preco.toFixed(2)} (alvo mín: R$ ${min.toFixed(2)})`;
      tipo = 'ABAIXO_MINIMO';
    } else if (max !== undefined && preco >= max) {
      alerta = `⬆️ ${ticker} subiu para R$ ${preco.toFixed(2)} (alvo máx: R$ ${max.toFixed(2)})`;
      tipo = 'ACIMA_MAXIMO';
    }
  }

  if (alerta) {
    results.push({
      json: {
        ticker,
        nome,
        preco,
        min,
        max,
        tipo,
        alerta,
        timestamp: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })
      }
    });
  }
}

if (results.length === 0) {
  results.push({ json: { sem_alerta: true } });
}

return results;

